try:
    print('>>> f = getattr')
    print('>>> x = NotImplemented')
    print('>>> y = 2.3456')
    print('>>> f(x, y)')
    f = getattr
    x = NotImplemented
    y = 2.3456
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
